        for nxt, km in adj.get(node, {}).items():
            if nxt not in done:
                heapq.heappush(heap, (cost + km, legs + 1, path + [nxt]))
    return None


def plan_drop_route(adj, origin, destination, drops):
    """Plan the shortest tour from origin to destination visiting all drops.

    Drops may be visited in any order; the route is the chain of shortest_path
    segments origin -> first drop -> ... -> last drop -> destination, joined
    without repeating the depot where they meet. Returns (total_km, path) for
    the cheapest visiting order, or None if no order gives a complete route.
    With no drops this is simply the shortest route from origin to destination.

    Raises ValueError if drops contains duplicates or more than 6 depots, and
    KeyError if origin, destination or any drop is not in adj.
