        path: List[str] = []
        prev = origin
        complete = True
        for node in order:
            seg = _shortest(adj, prev, node)
            if seg is None:
                complete = False
                break
            cost, seg_path = seg
            total += cost
            if not path:
                path = list(seg_path)
            else:
                path.extend(seg_path[1:])
            prev = node
        if not complete:
